import{_ as a,o as t,c as n,a3 as o}from"./chunks/framework.BlfGB29P.js";const i="/images/logic-studio/user-guide/function-plan-walkthrough-en.jpg",g=JSON.parse('{"title":"Function plan","description":"","frontmatter":{},"headers":[],"relativePath":"en/projects/logic-studio/user-guide/function-plan.md","filePath":"en/projects/logic-studio/user-guide/function-plan.md","lastUpdated":1795345553000}'),s={name:"en/projects/logic-studio/user-guide/function-plan.md"};function r(h,e,l,d,c,u){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="function-plan" tabindex="-1">Function plan <a class="header-anchor" href="#function-plan" aria-label="Permalink to &quot;Function plan&quot;">​</a></h1><h2 id="invert-a-signal-in-the-function-plan" tabindex="-1">Invert a signal in the function plan <a class="header-anchor" href="#invert-a-signal-in-the-function-plan" aria-label="Permalink to &quot;Invert a signal in the function plan&quot;">​</a></h2><h3 id="_1-open-the-plan-and-add-the-blocks" tabindex="-1">1. Open the plan and add the blocks <a class="header-anchor" href="#_1-open-the-plan-and-add-the-blocks" aria-label="Permalink to &quot;1. Open the plan and add the blocks&quot;">​</a></h3><p>Open the function plan from the project tree. In the palette search for <code>STATE_IN</code>, <code>NOT</code> and <code>STATE_OUT</code>, and click each to add it. Drag each block by its header to place them left to right in that order.</p><h3 id="_2-configure-the-input" tabindex="-1">2. Configure the input <a class="header-anchor" href="#_2-configure-the-input" aria-label="Permalink to &quot;2. Configure the input&quot;">​</a></h3><p>Open the settings for <code>STATE_IN</code> using the gear. Enter the entity ID of your test sensor or helper. The demo uses <code>binary_sensor.bewegung</code>. Set the signal type to <code>BOOL</code> and the demo input to <code>TRUE</code>.</p><h3 id="_3-configure-the-output" tabindex="-1">3. Configure the output <a class="header-anchor" href="#_3-configure-the-output" aria-label="Permalink to &quot;3. Configure the output&quot;">​</a></h3><p>Open the settings for <code>STATE_OUT</code>. Enter a suitable target entity ID. The demo uses <code>light.flur</code>. Leave output mode set to <code>BOOL</code>. A Boolean signal is either <code>TRUE</code> or <code>FALSE</code>.</p><h3 id="_4-wire-the-pins" tabindex="-1">4. Wire the pins <a class="header-anchor" href="#_4-wire-the-pins" aria-label="Permalink to &quot;4. Wire the pins&quot;">​</a></h3><p>Drag from the round <strong>Q</strong> output of <code>STATE_IN</code> to <strong>IN</strong> on <code>NOT</code>. Then drag from <strong>OUT</strong> on <code>NOT</code> to <strong>IN</strong> on <code>STATE_OUT</code>. The canvas header should show three blocks and two connections.</p><h3 id="_5-run-the-simulation" tabindex="-1">5. Run the simulation <a class="header-anchor" href="#_5-run-the-simulation" aria-label="Permalink to &quot;5. Run the simulation&quot;">​</a></h3><p>Click <strong>Simulate</strong> (the flask icon). The input shows <code>Demo: true</code>. <code>NOT</code> inverts the value, so <code>STATE_OUT</code> shows <code>Demo: false</code>. The simulation uses demo values and leaves the real light unchanged.</p><h3 id="_6-check-the-opposite-case" tabindex="-1">6. Check the opposite case <a class="header-anchor" href="#_6-check-the-opposite-case" aria-label="Permalink to &quot;6. Check the opposite case&quot;">​</a></h3><p>Set the demo input to <code>FALSE</code> and simulate again. The output should now show <code>true</code>. Use the reset simulation button to clear simulation state. Save the project to keep the plan.</p><p><a href="/images/logic-studio/user-guide/function-plan-walkthrough-en.jpg"><img src="'+i+'" alt="Function plan with STATE_IN, NOT and STATE_OUT. The demo input is true and the output is false."></a></p><p>If a wire is rejected, check both pin types. If the simulation reports a missing entity ID, check the input and output settings. Use the simulation button here. <strong>Play</strong> in the project toolbar starts the runtime.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><h3 id="canvas" tabindex="-1">Canvas <a class="header-anchor" href="#canvas" aria-label="Permalink to &quot;Canvas&quot;">​</a></h3><p>Drag, move and connect blocks. Zoom or fit the whole plan.</p><h3 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h3><p>Select a block to set a timer duration or counter target.</p><h3 id="ha-bindings" tabindex="-1">HA bindings <a class="header-anchor" href="#ha-bindings" aria-label="Permalink to &quot;HA bindings&quot;">​</a></h3><p>Choose an entity for the signal and an approved HA action for the output.</p><h3 id="simulation" tabindex="-1">Simulation <a class="header-anchor" href="#simulation" aria-label="Permalink to &quot;Simulation&quot;">​</a></h3><p>Toggle inputs and follow signal values at the pins.</p><h3 id="breakpoint-and-single-step" tabindex="-1">Breakpoint and single step <a class="header-anchor" href="#breakpoint-and-single-step" aria-label="Permalink to &quot;Breakpoint and single step&quot;">​</a></h3><p>Pause and advance one scan to inspect the values.</p><h3 id="auto-layout-and-pinning" tabindex="-1">Auto layout and pinning <a class="header-anchor" href="#auto-layout-and-pinning" aria-label="Permalink to &quot;Auto layout and pinning&quot;">​</a></h3><p>Arrange the plan while keeping pinned blocks in place.</p><h3 id="play-and-live-diagnostics" tabindex="-1">Play and live diagnostics <a class="header-anchor" href="#play-and-live-diagnostics" aria-label="Permalink to &quot;Play and live diagnostics&quot;">​</a></h3><p>Start the saved plan and inspect live values and errors.</p><h3 id="persistent-counters-and-latches" tabindex="-1">Persistent counters and latches <a class="header-anchor" href="#persistent-counters-and-latches" aria-label="Permalink to &quot;Persistent counters and latches&quot;">​</a></h3><p>Enable storage to keep values across app restarts. Editing the plan can reset them.</p><h2 id="if-something-goes-wrong" tabindex="-1">If something goes wrong <a class="header-anchor" href="#if-something-goes-wrong" aria-label="Permalink to &quot;If something goes wrong&quot;">​</a></h2><p>If a connection is refused, compare the types of its pins.</p>',35)])])}const f=a(s,[["render",r]]);export{g as __pageData,f as default};
